The two directories only contain subdirectories so far. Let me descend into them fully to make sure nothing is hidden further down.

```python
import os, datetime

for top in ["abb-tablegpt-5utytjj_", "kuma"]:
    print(f"=== Full tree: {top}/ ===")
    if not os.path.isdir(top):
        print("  (missing)\n"); continue
    for root, dirs, files in os.walk(top):
        depth = root.count(os.sep)
        print(f"  {'  '*depth}{os.path.basename(root) or root}/")
        for f in sorted(files):
            full = os.path.join(root, f)
            try:
                st = os.stat(full)
                print(f"  {'  '*(depth+1)}{f}  ({st.st_size} B, mtime={datetime.datetime.fromtimestamp(st.st_mtime)})")
            except Exception as e:
                print(f"  {'  '*(depth+1)}{f}  (err: {e})")
    print()
